 let minX=Math.min(...all.map(p=>p[0])),maxX=Math.max(...all.map(p=>p[0])),minY=Math.min(...all.map(p=>p[1])),maxY=Math.max(...all.map(p=>p[1]));const scale=Math.min(365/Math.max(maxX-minX,2),155/Math.max(maxY-minY,2)),cx=(minX+maxX)/2,cy=(minY+maxY)/2,P=p=>[220+(p[0]-cx)*scale,112-(p[1]-cy)*scale];let content='';
 function segment(a,b,color='#326ab3',arrow=false){const p=Array.isArray(a)?P(a):P(points[a]),q=Array.isArray(b)?P(b):P(points[b]);return `<line x1="${p[0]}" y1="${p[1]}" x2="${q[0]}" y2="${q[1]}" stroke="${color}" stroke-width="2.3"${arrow?' marker-end="url(#research-arrow)"':''}/>`;}
 if(m.sector&&m.sector.angle>0){const z=m.sector,o=P(z.center),r=z.r*scale,t=rad(z.angle),end=[o[0]+r*Math.cos(t),o[1]-r*Math.sin(t)];content+=z.angle>=360?`<circle cx="${o[0]}" cy="${o[1]}" r="${r}" fill="#c06c2a" fill-opacity=".15"/>`:`<path d="M ${o[0]} ${o[1]} L ${o[0]+r} ${o[1]} A ${r} ${r} 0 ${z.angle>180?1:0} 0 ${end[0]} ${end[1]} Z" fill="#c06c2a" fill-opacity=".18"/>`;}
 m.polygons.forEach((names,i)=>content+=`<polygon points="${names.map(n=>P(points[n]).join(',')).join(' ')}" fill="${i?'#c06c2a':'#147c78'}" fill-opacity=".09" stroke="${i?'#c06c2a':'#147c78'}" stroke-width="2.3"/>`);
 for(const c of m.circles){const o=P(points[c.center]);content+=`<circle cx="${o[0]}" cy="${o[1]}" r="${c.r*scale}" fill="none" stroke="${c.color||'#7b94a4'}" stroke-width="1.8"/>`;}
 for(const [a,b] of m.lines){const p=points[a],q=points[b],d=sub(q,p);if(norm(d)>EPS){const ext=mul(d,1.2);content+=segment(sub(p,ext),add(q,ext),'#7b94a4');}}
 for(const [a,b] of m.rays||[]){const p=points[a],q=points[b],d=sub(q,p);if(norm(d)>EPS)content+=segment(p,add(q,mul(d,1.5)),'#7b94a4');}
