 const form=el.querySelector('form'),select=form.querySelector('select'),box=el.querySelector('.research-controls'),feedback=el.querySelector('.research-feedback'),textarea=el.querySelector('textarea');select.value=state.prediction;textarea.value=state.observation;
 const emit=()=>{onChange?.(JSON.parse(JSON.stringify(state)));};
 function draw(){const m=model(id,state.values);el.querySelector('.research-figure').innerHTML=svg(m,d.title);for(const c of cs){const input=el.querySelector('[data-value="'+c.key+'"]');input.value=state.values[c.key];const n=el.querySelector('[data-number="'+c.key+'"]');if(n)n.textContent=fmt(state.values[c.key]);}el.querySelector('.research-readout').innerHTML=m.readout.map(t=>'<p>'+E(t)+'</p>').join('');}
 function opened(){box.hidden=!state.opened;select.disabled=state.opened;form.querySelector('button').disabled=state.opened;if(state.opened)feedback.textContent=state.prediction==='unsure'?'Теперь измени параметры и сформулируй наблюдение.':'Прогноз сохранён. Измени параметры и сравни наблюдение со своим предположением.';}
 form.addEventListener('submit',e=>{e.preventDefault();if(!select.value){feedback.textContent='Выбери предположение или «Пока не знаю».';return;}state.prediction=select.value;state.opened=true;state.firstValues={...state.values};opened();emit();});
 for(const c of cs)el.querySelector('[data-value="'+c.key+'"]').addEventListener(c.options?'change':'input',e=>{state.values[c.key]=c.options?e.target.value:Number(e.target.value);state.changed=state.changed||JSON.stringify(state.values)!==JSON.stringify(state.firstValues);draw();emit();});
